<?php require_once __DIR__.'/../api/bootstrap.php'; require_login(); $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$tipo=$_POST['tipo']??'';$nome=trim($_POST['nome']??'');$conteudo=trim($_POST['conteudo']??'');if(!in_array($tipo,['ATESTADO','LAUDO'],true)||$nome===''||$conteudo==='')$err='Preencha todos os campos.';else{$s=db()->prepare('INSERT INTO modelos_documento(medico_id,tipo,nome,conteudo) VALUES(?,?,?,?)');$s->execute([current_medico()['id'],$tipo,$nome,$conteudo]);audit_log('criar_modelo','modelos_documento',db()->lastInsertId());redirect_to('modelos/');}} render_header('Novo modelo'); ?><h1>Novo modelo</h1><?php if($err): ?><div class="error"><?=e($err)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="card"><div class="grid"><div><label>Tipo</label><select name="tipo"><option value="ATESTADO">Atestado</option><option value="LAUDO">Laudo</option></select></div><div><label>Nome</label><input name="nome" required></div></div><label>Conteúdo</label><textarea name="conteudo" rows="18" required></textarea><p class="muted">Campos: {{PACIENTE}}, {{CPF}}, {{CID}}, {{CID_DESCRICAO}}, {{MEDICO}}, {{CRM}}, {{ESPECIALIDADE}}, {{DATA}}, {{INICIO}}, {{FIM}}, {{DIAS}}, {{CONCLUSAO}}, {{HISTORICO}}, {{AVALIACAO}}, {{EXAMES}}, {{REPERCUSSAO}}.</p></div><button class="btn ok">Salvar</button></form><?php render_footer(); ?>